package types

import (
	"bytes"
	"crypto/ed25519"
	"fmt"
	"math/big"

	"filippo.io/edwards25519"
)

// ed25519PrimeOrder is the order of the prime subgroup generated by the
// Ed25519 basepoint. It is used to reject mixed-order points, not merely points
// that are entirely in the small torsion subgroup.
var ed25519PrimeOrder = func() *big.Int {
	order, ok := new(big.Int).SetString(
		"7237005577332262213973186563042994240857116359379907606001950938285454250989",
		10,
	)
	if !ok {
		panic("invalid Ed25519 prime order")
	}
	return order
}()

// ValidateEd25519PublicKey accepts only the canonical RFC 8032 encoding of an
// on-curve, non-small-order point in the Ed25519 prime-order subgroup.
//
// Public keys are not secret, so the variable-time subgroup check does not
// expose private material. Keeping the accepted point set this narrow also
// removes implementation-dependent Ed25519 edge cases from consensus.
func ValidateEd25519PublicKey(publicKey []byte) error {
	return validateEd25519Point("public key", publicKey)
}

// VerifyEd25519Signature verifies a signature only after validating both the
// public key and signature R as canonical prime-subgroup points and S as a
// canonical scalar. crypto/ed25519 then performs the signature equation check.
func VerifyEd25519Signature(publicKey, message, signature []byte) error {
	if err := ValidateEd25519PublicKey(publicKey); err != nil {
		return err
	}
	if len(signature) != ed25519.SignatureSize {
		return fmt.Errorf("signature must be %d bytes", ed25519.SignatureSize)
	}
	if err := validateEd25519Point("signature R", signature[:32]); err != nil {
		return err
	}
	if _, err := new(edwards25519.Scalar).SetCanonicalBytes(signature[32:]); err != nil {
		return fmt.Errorf("signature S is not a canonical Ed25519 scalar")
	}
	if !ed25519.Verify(ed25519.PublicKey(publicKey), message, signature) {
		return fmt.Errorf("invalid Ed25519 signature")
	}
	return nil
}

func validateEd25519Point(label string, encoded []byte) error {
	if len(encoded) != ed25519.PublicKeySize {
		return fmt.Errorf("%s must be %d bytes", label, ed25519.PublicKeySize)
	}
	point, err := new(edwards25519.Point).SetBytes(encoded)
	if err != nil {
		return fmt.Errorf("%s is not an Ed25519 curve point", label)
	}
	if !bytes.Equal(point.Bytes(), encoded) {
		return fmt.Errorf("%s encoding is noncanonical", label)
	}

	identity := edwards25519.NewIdentityPoint()
	if new(edwards25519.Point).MultByCofactor(point).Equal(identity) == 1 {
		return fmt.Errorf("%s is a small-order point", label)
	}

	// filippo.io/edwards25519 scalars are reduced modulo the subgroup order,
	// so [l]P cannot be expressed through ScalarMult. Use a straightforward
	// public-input double-and-add to test [l]P == identity.
	result := edwards25519.NewIdentityPoint()
	addend := new(edwards25519.Point).Set(point)
	for bit := 0; bit < ed25519PrimeOrder.BitLen(); bit++ {
		if ed25519PrimeOrder.Bit(bit) == 1 {
			result.Add(result, addend)
		}
		addend.Add(addend, addend)
	}
	if result.Equal(identity) != 1 {
		return fmt.Errorf("%s is not in the Ed25519 prime-order subgroup", label)
	}
	return nil
}
